package calc;

/** Signals any failure while evaluating an expression: syntax, division by zero, or overflow. */
public final class CalcException extends Exception {

    private static final long serialVersionUID = 1L;

    public CalcException(String message) {
        super(message, null, false, false);
    }
}

package calc;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;

/**
 * Entry point: reads one expression per line from standard input and prints
 * its value or {@code error}. Blank lines produce no output.
 */
public final class Main {

    /** Generous stack so deeply nested expressions do not overflow the recursive parser. */
    private static final long STACK_SIZE_BYTES = 1L << 30;

    private Main() {
    }

    public static void main(String[] args) throws InterruptedException {
        Thread worker = new Thread(null, Main::run, "calc", STACK_SIZE_BYTES);
        worker.start();
        worker.join();
    }

    private static void run() {
        // ISO-8859-1 maps every byte to a char, so arbitrary input bytes never fail decoding;
        // any non-ASCII byte is simply an invalid token.
        try (BufferedReader in = new BufferedReader(
                     new InputStreamReader(System.in, StandardCharsets.ISO_8859_1), 1 << 16);
             PrintWriter out = new PrintWriter(new BufferedWriter(
                     new OutputStreamWriter(System.out, StandardCharsets.US_ASCII), 1 << 16))) {
            String line;
            while ((line = readLine(in)) != null) {
                if (!isBlank(line)) {
                    out.print(evaluate(line));
                    out.print('\n');
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Reads a line terminated by {@code '\n'} only (unlike {@link BufferedReader#readLine()},
     * a {@code '\r'} is kept so that it is rejected as an invalid character).
     *
     * @return the line without its terminator, or {@code null} at end of input
     */
    private static String readLine(BufferedReader in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') {
                return sb.toString();
            }
            sb.append((char) c);
        }
        return sb.isEmpty() ? null : sb.toString();
    }

    private static String evaluate(String line) {
        try {
            return Long.toString(Parser.evaluate(line));
        } catch (CalcException | StackOverflowError e) {
            return "error";
        }
    }

    private static boolean isBlank(String line) {
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c != ' ' && c != '\t') {
                return false;
            }
        }
        return true;
    }
}

package calc;

/**
 * Recursive-descent evaluator for signed 64-bit integer expressions.
 *
 * <pre>
 * expr    := term    (('+' | '-') term)*
 * term    := unary   (('*' | '/' | '%') unary)*
 * unary   := '-' unary | primary
 * primary := NUMBER | '(' expr ')'
 * NUMBER  := [0-9]+
 * </pre>
 *
 * Spaces and tabs are permitted between tokens. All arithmetic is overflow-checked.
 */
public final class Parser {

    private final String src;
    private int pos;

    private Parser(String src) {
        this.src = src;
    }

    /** Evaluates a complete expression, throwing {@link CalcException} on any error. */
    public static long evaluate(String expression) throws CalcException {
        Parser parser = new Parser(expression);
        long value = parser.expr();
        parser.skipBlanks();
        if (parser.pos != parser.src.length()) {
            throw new CalcException("unexpected character at " + parser.pos);
        }
        return value;
    }

    private long expr() throws CalcException {
        long value = term();
        while (true) {
            int op = peek();
            if (op == '+') {
                pos++;
                value = apply('+', value, term());
            } else if (op == '-') {
                pos++;
                value = apply('-', value, term());
            } else {
                return value;
            }
        }
    }

    private long term() throws CalcException {
        long value = unary();
        while (true) {
            int op = peek();
            if (op == '*' || op == '/' || op == '%') {
                pos++;
                value = apply((char) op, value, unary());
            } else {
                return value;
            }
        }
    }

    private long unary() throws CalcException {
        if (peek() == '-') {
            pos++;
            long operand = unary();
            if (operand == Long.MIN_VALUE) {
                throw new CalcException("overflow in negation");
            }
            return -operand;
        }
        return primary();
    }

    private long primary() throws CalcException {
        int c = peek();
        if (c == '(') {
            pos++;
            long value = expr();
            if (peek() != ')') {
                throw new CalcException("expected ')' at " + pos);
            }
            pos++;
            return value;
        }
        if (isDigit(c)) {
            return number();
        }
        throw new CalcException("expected operand at " + pos);
    }

    private long number() throws CalcException {
        long value = 0;
        while (pos < src.length() && isDigit(src.charAt(pos))) {
            int digit = src.charAt(pos++) - '0';
            if (value > (Long.MAX_VALUE - digit) / 10) {
                throw new CalcException("literal out of range");
            }
            value = value * 10 + digit;
        }
        return value;
    }

    /** Applies a binary operator with exact 64-bit semantics. */
    private static long apply(char op, long left, long right) throws CalcException {
        try {
            return switch (op) {
                case '+' -> Math.addExact(left, right);
                case '-' -> Math.subtractExact(left, right);
                case '*' -> Math.multiplyExact(left, right);
                case '/' -> {
                    requireNonZero(right);
                    yield Math.divideExact(left, right);
                }
                case '%' -> {
                    requireNonZero(right);
                    // Long.MIN_VALUE % -1 is 0 in Java, matching the specification.
                    yield left % right;
                }
                default -> throw new IllegalArgumentException("unknown operator " + op);
            };
        } catch (ArithmeticException e) {
            throw new CalcException("overflow");
        }
    }

    private static void requireNonZero(long divisor) throws CalcException {
        if (divisor == 0) {
            throw new CalcException("division by zero");
        }
    }

    /** Skips blanks and returns the next character without consuming it, or -1 at end of input. */
    private int peek() {
        skipBlanks();
        return pos < src.length() ? src.charAt(pos) : -1;
    }

    private void skipBlanks() {
        while (pos < src.length()) {
            char c = src.charAt(pos);
            if (c != ' ' && c != '\t') {
                return;
            }
            pos++;
        }
    }

    private static boolean isDigit(int c) {
        return c >= '0' && c <= '9';
    }
}
